// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Вход по логину и паролю
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Выход (идемпотентный)
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe Текущий пользователь
	// (GET /api/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// AddCard Добавить слово в карточки
	// (POST /api/v1/cards)
	AddCard(w http.ResponseWriter, r *http.Request)
	// GetCardQueue Очередь карточек на сейчас
	// (GET /api/v1/cards/queue)
	GetCardQueue(w http.ResponseWriter, r *http.Request)
	// ReviewCard Оценить карточку
	// (POST /api/v1/cards/review)
	ReviewCard(w http.ResponseWriter, r *http.Request)
	// AnswerExercise Ответить на упражнение
	// (POST /api/v1/exercises/answer)
	AnswerExercise(w http.ResponseWriter, r *http.Request)
	// GetNextExercise Следующее упражнение
	// (GET /api/v1/exercises/next)
	GetNextExercise(w http.ResponseWriter, r *http.Request)
	// ListExerciseTopics Темы с рейтингом
	// (GET /api/v1/exercises/topics)
	ListExerciseTopics(w http.ResponseWriter, r *http.Request)
	// GetLearnBlock Блок слов для знакомства
	// (GET /api/v1/learn/block)
	GetLearnBlock(w http.ResponseWriter, r *http.Request)
	// IntroduceWords Ввести слова после знакомства
	// (POST /api/v1/learn/introduce)
	IntroduceWords(w http.ResponseWriter, r *http.Request)
	// GetPlacement Страница быстрого теста «знаю / не знаю»
	// (GET /api/v1/learn/placement)
	GetPlacement(w http.ResponseWriter, r *http.Request)
	// SubmitPlacement Отправить ответы быстрого теста
	// (POST /api/v1/learn/placement)
	SubmitPlacement(w http.ResponseWriter, r *http.Request)
	// GetLearnPreferences Настройки обучения
	// (GET /api/v1/learn/preferences)
	GetLearnPreferences(w http.ResponseWriter, r *http.Request)
	// PutLearnPreferences Сохранить настройки обучения
	// (PUT /api/v1/learn/preferences)
	PutLearnPreferences(w http.ResponseWriter, r *http.Request)
	// GetLearnStatus Состояние «Знакомства»
	// (GET /api/v1/learn/status)
	GetLearnStatus(w http.ResponseWriter, r *http.Request)
	// GetLevelSuggestion Предложение сменить уровень
	// (GET /api/v1/level/suggestion)
	GetLevelSuggestion(w http.ResponseWriter, r *http.Request)
	// DismissLevelSuggestion Спрятать предложение сменить уровень на 14 суток
	// (POST /api/v1/level/suggestion/dismiss)
	DismissLevelSuggestion(w http.ResponseWriter, r *http.Request)
	// GetMilestones Вехи
	// (GET /api/v1/milestones)
	GetMilestones(w http.ResponseWriter, r *http.Request)
	// ListMistakes Банк ошибок
	// (GET /api/v1/mistakes)
	ListMistakes(w http.ResponseWriter, r *http.Request)
	// GetProgressOverview Обзор прогресса
	// (GET /api/v1/progress/overview)
	GetProgressOverview(w http.ResponseWriter, r *http.Request)
	// GetProgressToday Прогресс за сегодня
	// (GET /api/v1/progress/today)
	GetProgressToday(w http.ResponseWriter, r *http.Request)
	// GetSettings Настройки обучения текущего пользователя
	// (GET /api/v1/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// PutSettings Сохранить настройки обучения (создаёт или заменяет целиком)
	// (PUT /api/v1/settings)
	PutSettings(w http.ResponseWriter, r *http.Request)
	// ListSheets Список шпаргалок
	// (GET /api/v1/sheets)
	ListSheets(w http.ResponseWriter, r *http.Request)
	// SetSheetFavorite Закрепить или открепить шпаргалку
	// (PUT /api/v1/sheets/favorite)
	SetSheetFavorite(w http.ResponseWriter, r *http.Request)
	// OpenSheet Открыть шпаргалку
	// (POST /api/v1/sheets/open)
	OpenSheet(w http.ResponseWriter, r *http.Request)
	// ReviewSheet Отметить шпаргалку проверенной
	// (POST /api/v1/sheets/review)
	ReviewSheet(w http.ResponseWriter, r *http.Request)
	// ListSources Загруженные источники данных с лицензиями и атрибуцией
	// (GET /api/v1/sources)
	ListSources(w http.ResponseWriter, r *http.Request)
	// SearchWords Поиск слова по началу (без учёта регистра)
	// (GET /api/v1/words)
	SearchWords(w http.ResponseWriter, r *http.Request)
	// ListWordExamples Примеры предложений для слова (из Tatoeba)
	// (GET /api/v1/words/examples)
	ListWordExamples(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// Login operation middleware
func (siw *ServerInterfaceWrapper) Login(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.Login(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

