type UnescapedCookieParamError struct {
	ParamName string
	Err       error
}

func (e *UnescapedCookieParamError) Error() string {
	return fmt.Sprintf("error unescaping cookie parameter '%s'", e.ParamName)
}

func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/auth/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings", wrapper.PutSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources", wrapper.ListSources)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/words", wrapper.SearchWords)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/words/examples", wrapper.ListWordExamples)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/cards", wrapper.AddCard)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cards/queue", wrapper.GetCardQueue)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/cards/review", wrapper.ReviewCard)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/exercises/next", wrapper.GetNextExercise)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/exercises/answer", wrapper.AnswerExercise)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/learn/status", wrapper.GetLearnStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/learn/block", wrapper.GetLearnBlock)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/learn/introduce", wrapper.IntroduceWords)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/learn/placement", wrapper.GetPlacement)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/learn/placement", wrapper.SubmitPlacement)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/learn/preferences", wrapper.GetLearnPreferences)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/learn/preferences", wrapper.PutLearnPreferences)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/exercises/topics", wrapper.ListExerciseTopics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/mistakes", wrapper.ListMistakes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sheets", wrapper.ListSheets)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sheets/open", wrapper.OpenSheet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/sheets/favorite", wrapper.SetSheetFavorite)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sheets/review", wrapper.ReviewSheet)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/level/suggestion", wrapper.GetLevelSuggestion)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/level/suggestion/dismiss", wrapper.DismissLevelSuggestion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/progress/today", wrapper.GetProgressToday)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/progress/overview", wrapper.GetProgressOverview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/milestones", wrapper.GetMilestones)

	return m
}
